VALUES ('SK10', 'SELANK', '10mg', 'Synthetic heptapeptide · anxiolytic research compound · ≥99% purity · For laboratory research use only', 'SELANK (10mg) is a synthetic peptide known for its ability to modulate GABA receptor activity and has been studied in research related to anxiety, stress, and cognitive function. This product is intended for research use in neurobiology and cognitive psychology studies examining the effects of SELANK on neural signaling and behavior.', 69, 0, 5, 0, 'data:image/jpeg;base64,', 'purity', 'storage', 'form', 'cc', unixepoch(), unixepoch());
INSERT OR IGNORE INTO products (code, name, size, tagline, description, price, stock_qty, low_stock_threshold, in_stock, image_url, purity, storage, form, source_site, created_at, updated_at)
VALUES ('XA10', 'SEMAX', '10mg', 'Synthetic Heptapeptide · Neuropeptide Analog · ≥99% purity · For laboratory research use only', 'SEMAX (10mg) is a synthetic peptide known for its ability to mimic the effects of natural SEMA4D, a protein involved in neural development and synaptic plasticity, making it suitable for research on neuronal signaling and circuit formation. This peptide has been used in studies examining the role of SEMA4D in regulating axon guidance, dendritic spine morphology, and synaptic function in various neural systems.', 69, 0, 5, 0, 'data:image/jpeg;base64,', 'purity', 'storage', 'form', 'cc', unixepoch(), unixepoch());
